import { index, pgTable, text } from "drizzle-orm/pg-core";

import { id, timestamps } from "../columns";

// MP3 bytes generated by the Voice Reader agent (via ElevenLabs TTS). Stored
// base64-encoded in a text column — simple and good enough for the demo
// since each file is ~30-80KB. Switch to object storage if the demo grows.
export const audioAsset = pgTable(
  "audio_asset",
  {
    id: id(),
    memberId: text("member_id").notNull(),
    text: text("text").notNull(),
    mimeType: text("mime_type").notNull().default("audio/mpeg"),
    bytesBase64: text("bytes_base64").notNull(),
    ...timestamps(),
  },
  (t) => [index("audio_asset_member_idx").on(t.memberId)],
);
